import { Container, Row, Col } from "react-bootstrap";
import ServiceCard from "./ServiceCard";
import privateOffice from "../../Assets/private-office.png";
import virtualOffice from "../../Assets/virtual-office.png";
import meetingRoom from "../../Assets/meeting-room.png";
import { useLanguage } from "../../context/LanguageContext.js";

function Services() {
  const { t } = useLanguage();

  const images = [privateOffice, virtualOffice, meetingRoom];
  const services = t.servicesList.map((service, index) => ({
    ...service,
    image: images[index],
  }));

  return (
    <Container style={{ marginTop: "100px", color: "#222" }}>
      <h1 className="text-center mb-5" style={{ color: "#007e6a", fontWeight: "700" }}>
        {t.service}
      </h1>
      <Row className="g-4">
        {services.map((service, idx) => (
          <Col key={idx} md={6} lg={4} className="d-flex">
            <ServiceCard {...service} />
          </Col>
        ))}
      </Row>
    </Container>
  );
}

export default Services;
