import { useState, useEffect } from "react";
import Navbar from "react-bootstrap/Navbar";
import Nav from "react-bootstrap/Nav";
import Container from "react-bootstrap/Container";
import Button from "react-bootstrap/Button";
import { Link } from "react-router-dom";
import {
  AiOutlineHome,
  AiOutlineFundProjectionScreen,
  AiOutlineUser,
  AiOutlineGlobal,
} from "react-icons/ai";
import "../../src/style.css"; // تأكد إن فيه CSS للوضعين الداكن والفاتح
import { useLanguage } from "../context/LanguageContext"; // بدل ما تستخدم ترجمة محلية

const translations = {
  en: {
    home: "Home",
    about: "About",
    services: "Services",
    switchToArabic: "عربي",
    switchToEnglish: "English",
  },
  ar: {
    home: "الرئيسية",
    about: "من نحن",
    services: "خدماتنا",
    switchToArabic: "عربي",
    switchToEnglish: "English",
  },
};

function NavBar() {
  const [expand, updateExpanded] = useState(false);
  const [navColour, updateNavbar] = useState(false);

  const { language, toggleLanguage, t } = useLanguage(); // استخدام الترجمة

  useEffect(() => {
    window.addEventListener("scroll", scrollHandler);
    return () => window.removeEventListener("scroll", scrollHandler);
  }, []);

  function scrollHandler() {
    if (window.scrollY >= 20) updateNavbar(true);
    else updateNavbar(false);
  }

  useEffect(() => {
    document.body.setAttribute("dir", language === "ar" ? "rtl" : "ltr");
  },);

  return (
    <Navbar
      expanded={expand}
      fixed="top"
      expand="md"
      className={navColour ? "sticky" : "navbar"}

    >
      <Container>
        <Navbar.Brand as={Link} to="/" className="d-flex">
          <h2 style={{ color: '#007e6a', fontWeight: '700' }}>
            {t.logo}
          </h2>
        </Navbar.Brand>

        <Navbar.Toggle
          aria-controls="responsive-navbar-nav"
          onClick={() => updateExpanded(expand ? false : "expanded")}
        >
          <span></span>
          <span></span>
          <span></span>
        </Navbar.Toggle>

        <Navbar.Collapse id="responsive-navbar-nav">
          <Nav className="ms-auto flex-column flex-md-row align-items-start align-items-md-center gap-2">
            <Nav.Item>
              <Nav.Link as={Link} to="/" onClick={() => updateExpanded(false)}>
                <AiOutlineHome style={{ marginBottom: "2px" }} /> {t.home}
              </Nav.Link>
            </Nav.Item>

            <Nav.Item>
              <Nav.Link as={Link} to="/about" onClick={() => updateExpanded(false)}>
                <AiOutlineUser style={{ marginBottom: "2px" }} /> {t.about}
              </Nav.Link>
            </Nav.Item>

            <Nav.Item>
              <Nav.Link as={Link} to="/services" onClick={() => updateExpanded(false)}>
                <AiOutlineFundProjectionScreen style={{ marginBottom: "2px" }} />{" "}
                {t.service}
              </Nav.Link>
            </Nav.Item>

            {/* زر الترجمة */}
            <Nav.Item className="mt-2 mt-md-0">
              <Button
                variant="outline-light"
                size="sm"
                onClick={toggleLanguage}
                className="d-flex align-items-center gap-1"
              >
                <AiOutlineGlobal />
                {language === "en" ? t.switchToArabic : t.switchToEnglish}
              </Button>
            </Nav.Item>
          </Nav>

        </Navbar.Collapse>
      </Container>
    </Navbar>
  );
}

export default NavBar;
