import { useEffect } from "react";
import GitHubCalendar from "react-github-calendar";
import { Row } from "react-bootstrap";
import { useLanguage } from "../../context/LanguageContext.js";
import ReactTooltip from 'react-tooltip';

function Engagement() {
  const { t, language } = useLanguage();

  useEffect(() => {
    ReactTooltip.rebuild(); // يعيد بناء التولتيب لما يتغير المحتوى
  });

  return (
    <Row style={{ justifyContent: "center", paddingBottom: "10px" }}>
      <h1 className="project-heading" style={{ paddingBottom: "20px" }}>
        {t.engagementTitle.split(' ').map((word, i) => (
          word.toLowerCase() === (language === "ar" ? "أنشطتنا" : "engagement") ? (
            <strong key={i} className="purple">{word}</strong>
          ) : (
            word + (i !== t.engagementTitle.split(' ').length - 1 ? " " : "")
          )
        ))}
      </h1>

      <p
        style={{
          color: "rgb(187, 93, 242)",
          maxWidth: "600px",
          textAlign: "center",
          marginBottom: "20px",
        }}
      >
        {t.engagementDescription}
      </p>

      <GitHubCalendar
        username="soumyajit4419"
        blockSize={15}
        blockMargin={5}
        color="#bb5df2"
        fontSize={16}
        showWeekdayLabels={true}
        transformData={data => {
          return data.map(day => {
            const formattedDate = new Date(day.date).toLocaleDateString(
              language === "ar" ? "ar-EG" : "en-US",
              { day: "numeric", month: "long", year: "numeric" }
            );

            const tooltipText = day.count === 0
              ? (language === "ar" ? "لا توجد نشاطات" : "No activity")
              : language === "ar"
                ? `${day.count} نشاط${day.count > 1 ? "ات" : ""} في ${formattedDate}`
                : `${day.count} contributions on ${formattedDate}`;

            return {
              ...day,
              'data-tip': tooltipText,
              'data-for': 'github-calendar-tooltip',
            };
          });
        }}
      />

      <ReactTooltip id="github-calendar-tooltip" place="top" type="dark" effect="solid" />
    </Row>
  );
}

export default Engagement;
