import { Col, Row } from "react-bootstrap";
import { FaWifi, FaCoffee, FaPrint, FaPhoneAlt, FaRegCalendarCheck } from "react-icons/fa";
import { useLanguage } from "../../context/LanguageContext.js";

function Facilities() {
  const { t } = useLanguage();

  // أيقونات بنفس ترتيب النصوص في t.facilities
  const icons = [
    <FaWifi />,
    <FaCoffee />,
    <FaPrint />,
    <FaPhoneAlt />,
    <FaRegCalendarCheck />,
  ];

  return (
    <Row style={{ justifyContent: "center", paddingBottom: "50px" }}>
      {t.facilities.map((facility, index) => (
        <Col xs={6} md={2} className="tech-icons" key={index}>
          {icons[index]} <br />
          <span style={{ fontSize: "30px" }}>{facility}</span>
        </Col>
      ))}
    </Row>
  );
}

export default Facilities;
