import { Container, Row, Col, Card } from "react-bootstrap";
import { useLanguage } from "../../context/LanguageContext"; // تأكد من المسار الصحيح

import img12 from "../../Assets/private-office-12.png";
import img16 from "../../Assets/private-office-16.png";
import img18 from "../../Assets/private-office-18.png";
import img25 from "../../Assets/private-office-25.png";

const images = [img12, img16, img18, img25];

function PrivateOffice() {
  const { t , language} = useLanguage();
  const offices = t.privateOffices;

  return (
    <Container style={{ marginTop: "100px" }} className="custom-container">
      <h1 className="mb-5 text-center"  style={{ color: '#007e6a',  fontWeight: '700'}}>{t.servicesList[0].title}</h1>
      <Row>
        {offices.map((office, index) => (
          <Col md={4} key={index} className="mb-4">
            <Card className="h-100 shadow bg-dark text-white">
              <Card.Img
                variant="top"
                src={images[index]}
                style={{ height: "220px", objectFit: "cover" }}
              />
              <Card.Body>
                <Card.Title>{office.title}</Card.Title>
                <Card.Subtitle style={{ color: '#007e6a',  fontWeight: '700'}} className="mb-2" >
                  {office.price}
                </Card.Subtitle>
                <h5 className="mt-3">
                  {language === "en" ? "Room Details" : "تفاصيل الغرفة"}

                </h5>
                <ul>
                  {office.details.map((detail, i) => (
                    <li key={i}>{detail}</li>
                  ))}
                </ul>
              </Card.Body>
            </Card>
          </Col>
        ))}
      </Row>
    </Container>
  );
}

export default PrivateOffice;
