import { Container, Row, Col, Card } from "react-bootstrap";
import { useLanguage } from "../../context/LanguageContext.js";  // عدل المسار حسب مكان ملف الترجمة

function VirtualOffice() {
  const { t } = useLanguage();

  const packages = t.virtualOfficePackages;

  return (
    <Container style={{ marginTop: "100px" }} className="custom-container">
      <h1 className="text-center mb-5" style={{ color: '#007e6a',  fontWeight: '700'}} >{t.virtualOfficePackagesTitle}</h1>
      <Row>
        {packages.map((pkg, index) => (
          <Col md={4} key={index} className="mb-4">
            <Card className="h-100 shadow bg-dark text-white">
              <Card.Body>
                <Card.Title>{pkg.title}</Card.Title>
                <Card.Subtitle style={{ color: '#007e6a',  fontWeight: '700'}} className="mb-3">{pkg.price}</Card.Subtitle>
                <ul>
                  {pkg.details.map((item, i) => (
                    <li key={i}>{item}</li>
                  ))}
                </ul>
              </Card.Body>
            </Card>
          </Col>
        ))}
      </Row>
    </Container>
  );
}

export default VirtualOffice;
