import { useEffect } from "react";
import Card from "react-bootstrap/Card";
import { ImPointRight } from "react-icons/im";
import { useLanguage } from "../../context/LanguageContext.js"; // عدل المسار حسب مكان ملف اللغة

function AboutCard() {
  const { language, toggleLanguage, t } = useLanguage(); // استخدام الترجمة


  useEffect(() => {
    document.body.setAttribute("dir", language === "ar" ? "rtl" : "ltr");
  },);


  return (
    <Card className="quote-card-view">
      <Card.Body>
        <blockquote className="blockquote mb-0" >
          <p style={{ textAlign: "justify" }} dangerouslySetInnerHTML={{ __html: t.aboutDescription }} />

          <ul>
            {t.aboutCulturePoints.map((point, idx) => (
              <li key={idx} className="about-activity">
                <ImPointRight /> {point}
              </li>
            ))}
          </ul>

          <p style={{ color: "rgb(40, 7, 59)", fontWeight: "bolder" }}>
            {t.aboutQuote}
          </p>
          <footer className="blockquote-footer">{t.aboutQuoteAuthor}</footer>
        </blockquote>
      </Card.Body>
    </Card>
  );
}

export default AboutCard;
