import { Container, Row, Col, Card } from "react-bootstrap";
import { useLanguage } from "../../context/LanguageContext.js";

function MeetingRoomPackages() {
  const { t } = useLanguage();
  const meetingRoomPackages = t.meetingRoomPackages || {};

  return (
    <Container style={{ marginTop: "100px" }} className="custom-container">
      <h1 style={{ color: '#007e6a',  fontWeight: '700'}} className="text-center mb-4">{meetingRoomPackages.title}</h1>

      <p className="text-center" style={{ color: '#007e6a',  fontWeight: '700'}}>
        <strong>{meetingRoomPackages.hourlyRate}</strong>
      </p>

      <h3 className="mt-5" style={{ color: '#007e6a',  fontWeight: '700'}}>{meetingRoomPackages.monthlyTitle}</h3>
      <Row>
        {meetingRoomPackages.monthly?.map((pkg, index) => (
          <Col md={4} key={index} className="mb-4">
            <Card className="h-100 shadow-sm bg-dark text-white">
              <Card.Body>
                <Card.Title>{pkg.title}</Card.Title>
                <Card.Text>
                  <strong>{pkg.hours}</strong>
                  <br />
                  {pkg.price}
                </Card.Text>
              </Card.Body>
            </Card>
          </Col>
        ))}
      </Row>

      <h3 style={{ color: '#007e6a',  fontWeight: '700'}} className="mt-5">{meetingRoomPackages.yearlyTitle}</h3>
      <Row>
        {meetingRoomPackages.yearly?.map((pkg, index) => (
          <Col md={4} key={index} className="mb-4">
            <Card className="h-100 shadow-sm bg-dark text-white">
              <Card.Body>
                <Card.Title>{pkg.title}</Card.Title>
                <Card.Text>
                  <strong>{pkg.hours}</strong>
                  <br />
                  {pkg.price}
                </Card.Text>
              </Card.Body>
            </Card>
          </Col>
        ))}
      </Row>

      <h3 className="mt-5" style={{ color: '#007e6a',  fontWeight: '700'}}>{meetingRoomPackages.includedServicesTitle}</h3>
      <ul>
        {meetingRoomPackages.includedServices?.map((service, i) => (
          <li style={{ color: '#007e6a',  fontWeight: '700'}} key={i}>{service}</li>
        ))}
      </ul>
    </Container>
  );
}

export default MeetingRoomPackages;
